INSERT INTO files (area_id, filename, descr, size, uploader, uploaded_at, status, free, content, ctype) VALUES (13, 'COOKBOOK.TXT', 'The Underground Cookbook, vol. 1', 772, 'SysOp', 1792371656037, 'approved', 1, '          THE UNDERGROUND COOKBOOK - vol. 1
          compiled by OUTFL0W for all the dudes up past 3am

 You downloaded this thinking it was something dangerous. It is: these
 are the nachos that kept the 617 scene alive through the winter.

 RECIPE #1: COURIER NACHOS
  - one bag of tortilla chips, the cheap kind
  - a lot of shredded cheddar. More than that.
  - pickled jalapenos from the jar in the door of the fridge
  Microwave 90 seconds. Eat at keyboard. Do not get cheese on the 3.5".

 RECIPE #2: THE 0-DAY SANDWICH
  - peanut butter, potato chips, white bread
  Smash the chips into the PB. Ready before your download finishes.

 RECIPE #3: JOLT & POP-TARTS
  It is not a recipe. It is a lifestyle.

 Greetz to everyone''s mom who let them use the phone line.
', 'text/plain');
INSERT INTO files (area_id, filename, descr, size, uploader, uploaded_at, status, free, content, ctype) VALUES (13, 'PH34R.TXT', 'The PH34R Manifesto, by a 15 yr old', 587, 'SysOp', 1792371656037, 'approved', 1, '               T H E   P H 3 4 R   M A N i F E S T 0

